import{A as e,f as t,h as n,t as r}from"./chunks/plugin-vue_export-helper.I53torQa.js";var i=JSON.parse(`{"title":"GPU 与昇腾：大模型训练与推理生态对比","description":"从硬件、软件栈、训练框架、推理引擎和迁移成本比较 NVIDIA GPU 与昇腾 NPU，说明不同场景下的选型依据、验证方法和常见误区。","frontmatter":{"title":"GPU 与昇腾：大模型训练与推理生态对比","description":"从硬件、软件栈、训练框架、推理引擎和迁移成本比较 NVIDIA GPU 与昇腾 NPU，说明不同场景下的选型依据、验证方法和常见误区。"},"headers":[],"relativePath":"ascend/platform/gpu-vs-ascend.md","filePath":"ascend/platform/gpu-vs-ascend.md","lastUpdated":1795484948000}`),a={name:`ascend/platform/gpu-vs-ascend.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="gpu-与昇腾-大模型训练与推理生态对比" tabindex="-1">GPU 与昇腾：大模型训练与推理生态对比 <a class="header-anchor" href="#gpu-与昇腾-大模型训练与推理生态对比" aria-label="Permalink to “GPU 与昇腾：大模型训练与推理生态对比”">​</a></h1><p>本文比较 NVIDIA GPU 与华为昇腾 NPU 在大模型训练和推理中的实际差异，重点讨论硬件、软件栈、框架支持和迁移成本。资料以厂商文档和开源项目说明为准，核对日期为 2026 年 11 月 24 日。</p><p>不同资料的价格、MFU 和 tokens/s 往往采用不同模型、并行策略与测试条件，本文不用这些数字给平台排名。选型时先确认工作负载，再用同一模型和指标做验证。</p><h2 id="_1-先看结论" tabindex="-1">1. 先看结论 <a class="header-anchor" href="#_1-先看结论" aria-label="Permalink to “1. 先看结论”">​</a></h2><p>NVIDIA 的优势是成熟的 CUDA 生态、丰富的优化算子和较多可直接复用的研究代码。昇腾可以依托 torch_npu、CANN、MindSpeed 和 vLLM-Ascend 覆盖常见训练与推理流程，但具体模型、算子和版本的支持范围需要逐项核对。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>场景</th><th>优先考虑</th><th>选择依据</th></tr></thead><tbody><tr><td>已有大量自定义 CUDA Kernel</td><td>NVIDIA GPU</td><td>直接复用现有实现，避免重写和精度验证</td></tr><tr><td>标准 PyTorch 微调</td><td>两者都可评估</td><td>GPU 生态更成熟；昇腾可用 LLaMA-Factory、ms-swift 等框架</td></tr><tr><td>大规模预训练</td><td>按集群和软件路径实测</td><td>比较有效吞吐、扩展效率和长时间稳定性，不只看单卡峰值</td></tr><tr><td>已有昇腾设备或国产化部署要求</td><td>昇腾 NPU</td><td>复用现有资源，满足供应和部署约束</td></tr><tr><td>vLLM 在线推理</td><td>两者都可评估</td><td>先查目标模型在 vLLM 与 vLLM-Ascend 中的支持状态，再比较 SLO</td></tr><tr><td>MoE 训练或推理</td><td>按通信路径选择</td><td>Scale-Up 互联、专家并行实现和通信算子通常比单卡峰值更关键</td></tr><tr><td>追求最低成本</td><td>实测后决定</td><td>比较单位有效产出成本，不能只比较卡时价格</td></tr></tbody></table></div><p>两种平台不存在脱离工作负载的固定优劣。对标准模型和成熟框架，迁移通常不难；对自定义算子、复杂并行和极限性能优化，成本会明显增加。</p><h2 id="_2-硬件与集群-先统一比较口径" tabindex="-1">2. 硬件与集群：先统一比较口径 <a class="header-anchor" href="#_2-硬件与集群-先统一比较口径" aria-label="Permalink to “2. 硬件与集群：先统一比较口径”">​</a></h2><h3 id="_2-1-设备内存和互联" tabindex="-1">2.1 设备内存和互联 <a class="header-anchor" href="#_2-1-设备内存和互联" aria-label="Permalink to “2.1 设备内存和互联”">​</a></h3><p>下表列出部分公开规格，便于确定容量和互联的分析起点。不同产品的精度、稀疏条件和带宽方向并不完全一致，因此不在这张表里排列算力高低。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>产品</th><th>设备内存与带宽</th><th>互联信息</th></tr></thead><tbody><tr><td>NVIDIA H100 SXM</td><td>80 GB；3.35 TB/s</td><td>NVLink 900 GB/s</td></tr><tr><td>NVIDIA H200 SXM</td><td>141 GB；4.8 TB/s</td><td>NVLink 900 GB/s</td></tr><tr><td>NVIDIA B200 SXM</td><td>180 GB；最高 8 TB/s</td><td>NVLink 5，GPU 间带宽 1800 GB/s</td></tr><tr><td>Atlas A3 所用昇腾 NPU</td><td>产品页按每 NPU 128 GB、最高 3.2 TB/s 列出</td><td>Atlas 900 A3 产品页列出双向 784 GB/s D2D 带宽</td></tr><tr><td>Atlas 350（950PR）</td><td>112 GB HBM；1.4 TB/s</td><td>2 卡互联双向最高 424 GB/s；4 卡全互联双向最高 318 GB/s</td></tr><tr><td>Atlas 950 SuperPoD 所用 950DT</td><td>产品页按每 NPU 96 GB、最高 4.0 TB/s 列出</td><td>采用灵衢 2.0；具体带宽按产品和组网配置核对</td></tr></tbody></table></div><p>这些数字分别来自 NVIDIA、华为企业业务和昇腾社区产品页。[1][2][3][4][5][6][7] H100/H200 的算力参数还涉及稀疏条件，B200 的内存容量在不同产品资料中也可能采用不同配置。引用时应回到目标 SKU 的原始规格表。</p><p>设备内存主要用于容纳权重、激活、梯度、优化器状态和 KV Cache。容量不足时，需要分片、量化或增加设备。内存带宽影响权重和中间数据的供给能力，但不能直接等同于应用吞吐。</p><h3 id="_2-2-scale-up-与-scale-out" tabindex="-1">2.2 Scale-Up 与 Scale-Out <a class="header-anchor" href="#_2-2-scale-up-与-scale-out" aria-label="Permalink to “2.2 Scale-Up 与 Scale-Out”">​</a></h3><ul><li><strong>Scale-Up</strong> 关注服务器或超节点内部的高速互联，适合张量并行、专家并行和远端内存访问等频繁通信。</li><li><strong>Scale-Out</strong> 通过 InfiniBand、RoCE、UBoE 等网络连接更多节点或超节点，用于扩大集群规模。</li></ul><p>NVIDIA 常见组合是 NVLink/NVSwitch 加 InfiniBand 或 RoCE。昇腾 A3 使用 HCCS/灵衢 UB 等互联，950 引入灵衢 2.0、URMA、UB Memory 和 CCU。CloudMatrix384 论文还分别描述了 UB、RDMA 和 VPC 三个网络平面，不能把数据中心业务网络与 NPU 通信平面混为一谈。[8]</p><p>统一编址只表示资源可以按相应地址体系访问，不表示远端内存与本地 HBM 具有相同的时延和带宽。评估 MoE 或大规模推理时，应分别测量节点内、同超节点跨节点和跨超节点通信。</p><h2 id="_3-软件栈-接口相近-实现不同" tabindex="-1">3. 软件栈：接口相近，实现不同 <a class="header-anchor" href="#_3-软件栈-接口相近-实现不同" aria-label="Permalink to “3. 软件栈：接口相近，实现不同”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>层级</th><th>NVIDIA GPU</th><th>昇腾 NPU</th></tr></thead><tbody><tr><td>基础框架</td><td>PyTorch、JAX、TensorFlow</td><td>MindSpore；PyTorch + torch_npu</td></tr><tr><td>运行时与编译</td><td>CUDA Runtime、CUDA Graph 等</td><td>CANN、GE、Runtime、AOE 等</td></tr><tr><td>集合通信</td><td>NCCL</td><td>HCCL</td></tr><tr><td>分布式训练</td><td>Megatron-LM、DeepSpeed、FSDP</td><td>MindSpeed-LLM、MindSpeed-MM、Megatron 适配路径、FSDP 等</td></tr><tr><td>推理引擎</td><td>vLLM、TensorRT-LLM、SGLang、Triton</td><td>vLLM-Ascend、MindIE、SGLang 适配路径</td></tr><tr><td>自定义算子</td><td>CUDA、Triton、CUTLASS</td><td>Ascend C、TBE、Triton-Ascend</td></tr><tr><td>性能分析</td><td>Nsight、PyTorch Profiler</td><td>msprof、MindStudio 等</td></tr></tbody></table></div><p>torch_npu 是 PyTorch 的昇腾设备后端和算子适配层，不是 CUDA Kernel 的自动转换器。[9] 标准 PyTorch 算子可以复用不少模型代码，但自定义 CUDA 扩展、特定 Attention 实现和通信优化通常需要替换或重新实现。</p><p>vLLM-Ascend 则提供了复用 vLLM 接口和部署习惯的路径。其模型页面把支持状态区分为 Supported、Experimental、Unverified、Unmaintained 和 Unsupported，并进一步列出硬件、图模式、并行和量化能力。[10] “vLLM 支持某个模型”不表示该模型在 vLLM-Ascend 上具有相同的功能和性能。</p><h2 id="_4-训练与推理框架怎么选" tabindex="-1">4. 训练与推理框架怎么选 <a class="header-anchor" href="#_4-训练与推理框架怎么选" aria-label="Permalink to “4. 训练与推理框架怎么选”">​</a></h2><h3 id="_4-1-训练与后训练" tabindex="-1">4.1 训练与后训练 <a class="header-anchor" href="#_4-1-训练与后训练" aria-label="Permalink to “4.1 训练与后训练”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>需求</th><th>可选方案</th><th>核对重点</th></tr></thead><tbody><tr><td>快速 SFT、LoRA</td><td>LLaMA-Factory、ms-swift</td><td>模型、训练方式、硬件和融合算子是否在支持列表中</td></tr><tr><td>大规模预训练</td><td>Megatron-LM、MindSpeed-LLM</td><td>TP/PP/DP/CP/EP 组合、通信效率和长稳训练</td></tr><tr><td>GRPO、PPO 等后训练</td><td>verl、ms-swift、MindSpeed RL 等</td><td>rollout 引擎、训练后端、精度和模型组合</td></tr><tr><td>多模态训练</td><td>MindSpeed-MM、ms-swift</td><td>模型架构、数据管线和多模态算子</td></tr><tr><td>自定义训练算子</td><td>CUDA、Ascend C、TBE、Triton-Ascend</td><td>精度、性能、维护成本和版本兼容性</td></tr></tbody></table></div><p>LLaMA-Factory 的 NPU 文档列出了 Atlas A2/A3 和 950 系列，以及 PT、SFT、RM、DPO、Full、Freeze、LoRA、DDP、FSDP、FSDP2 和 DeepSpeed 支持情况。[11] ms-swift 提供训练、推理和部署能力，但其文档明确列出了不支持或尚未完整验证的项目，例如 QLoRA 和使用 SGLang 作为部署后端。[12] 选型应阅读当前版本的支持范围，而不是只看“支持 NPU”的概括。</p><p>verl 的昇腾文档提供 vLLM 或 SGLang 与 FSDP/Megatron 的组合方式。[13] 这类 RL 框架同时管理训练和 rollout，任何一端的模型或算子不受支持，都会影响整个流程。</p><h3 id="_4-2-推理与部署" tabindex="-1">4.2 推理与部署 <a class="header-anchor" href="#_4-2-推理与部署" aria-label="Permalink to “4.2 推理与部署”">​</a></h3><ul><li><strong>vLLM / vLLM-Ascend</strong>：适合评估统一的 vLLM 使用路径，先检查模型和功能支持，再做吞吐与时延测试。</li><li><strong>TensorRT-LLM</strong>：适合需要 NVIDIA 深度优化、量化和图优化的场景。</li><li><strong>MindIE</strong>：适合采用华为原生推理栈的部署环境。</li><li><strong>SGLang 及其 NPU 适配路径</strong>：适合需要结构化生成和复杂请求处理的场景，支持情况随后端和版本而变。</li></ul><p>推理评估至少应固定模型、权重精度、输入输出长度、并发数、批量、并行策略和 KV Cache 配置。训练关注稳定步时、有效吞吐、MFU 和扩展效率；在线推理则要同时记录 TTFT、TPOT、吞吐及 P95/P99 尾时延。</p><h2 id="_5-从-cuda-迁移到昇腾-按代码类型评估" tabindex="-1">5. 从 CUDA 迁移到昇腾：按代码类型评估 <a class="header-anchor" href="#_5-从-cuda-迁移到昇腾-按代码类型评估" aria-label="Permalink to “5. 从 CUDA 迁移到昇腾：按代码类型评估”">​</a></h2><h3 id="_5-1-先分类-不先估工期" tabindex="-1">5.1 先分类，不先估工期 <a class="header-anchor" href="#_5-1-先分类-不先估工期" aria-label="Permalink to “5.1 先分类，不先估工期”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>代码类型</th><th>迁移工作</th><th>主要风险</th></tr></thead><tbody><tr><td>标准 PyTorch 模型</td><td>安装配套环境，调整设备与通信后端</td><td>个别算子回退、精度或布局差异</td></tr><tr><td>使用成熟训练框架的模型</td><td>核对框架支持矩阵，替换不兼容组件</td><td>分布式策略和自定义扩展</td></tr><tr><td>自定义 CUDA Kernel</td><td>用现有 NPU 算子替代，或以 Ascend C/TBE 重写</td><td>数值一致性、性能退化和维护成本</td></tr><tr><td>复杂 MoE 通信与并行</td><td>重新验证 EP、通信库、拓扑和调度</td><td>All-to-All 时延、负载不均和跨节点稳定性</td></tr><tr><td>生产推理服务</td><td>验证模型、量化、连续批处理、KV Cache 和监控</td><td>尾时延、吞吐、故障恢复与版本升级</td></tr></tbody></table></div><p>迁移成本不只是修改 API。精度对齐、性能调优、长时间测试和后续版本维护通常更耗时，因此不宜在测试前给出统一的“几周”或“几人月”估算。</p><h3 id="_5-2-推荐的迁移顺序" tabindex="-1">5.2 推荐的迁移顺序 <a class="header-anchor" href="#_5-2-推荐的迁移顺序" aria-label="Permalink to “5.2 推荐的迁移顺序”">​</a></h3><ol><li><strong>盘点依赖</strong>：记录模型、算子、权重精度、并行策略、推理引擎和自定义扩展。</li><li><strong>锁定兼容组合</strong>：按官方矩阵匹配驱动、固件、CANN、PyTorch、torch_npu、框架和推理引擎，避免只升级其中一个组件。</li><li><strong>先做单设备 smoke test</strong>：检查设备可见性、内存分配、基础算子和模型前向结果。</li><li><strong>做数值对齐</strong>：使用固定输入比较输出、损失、梯度和评估指标，定位回退算子。</li><li><strong>再做性能优化</strong>：通过 Profiler 检查算子、数据搬运、Host 同步、通信和流水线，而不是先改模型结构。</li><li><strong>完成系统验收</strong>：覆盖多卡、多节点、长序列、高并发、故障恢复和长时间运行。</li></ol><h3 id="_5-3-常见误区" tabindex="-1">5.3 常见误区 <a class="header-anchor" href="#_5-3-常见误区" aria-label="Permalink to “5.3 常见误区”">​</a></h3><ul><li>把“能够运行”当成“性能相当”。</li><li>把 GPU 的支持列表当成昇腾的支持列表。</li><li>只替换 <code>torch.cuda</code> 或 NCCL 名称，不检查自定义算子和通信路径。</li><li>忽略权重精度、数据布局和量化方式的差异。</li><li>用单卡峰值推算集群吞吐，或用低并发结果代表生产高峰。</li></ul><h2 id="_6-成本与验收-比较有效产出" tabindex="-1">6. 成本与验收：比较有效产出 <a class="header-anchor" href="#_6-成本与验收-比较有效产出" aria-label="Permalink to “6. 成本与验收：比较有效产出”">​</a></h2><p>TCO 应包括设备或云资源、供电与散热、迁移和调优人力、测试验收、故障恢复以及后续维护。卡时价格只是其中一项。</p><p>可以使用下面的指标做同口径比较：</p><ul><li>训练：完成目标精度和 token 数所需的总成本、总时间、能耗与人力。</li><li>推理：满足 TTFT、TPOT 和尾时延约束时，每百万有效输入/输出 token 的成本。</li><li>集群：达到目标扩展效率和稳定运行时长所需的有效资源，而非名义卡数。</li></ul><p>验收时保留模型版本、权重精度、软件版本、并行策略、原始日志和监控数据。没有这些信息，不同平台之间的性能和成本数字很难复现，也不适合用来决策。</p><h2 id="_7-参考资料" tabindex="-1">7. 参考资料 <a class="header-anchor" href="#_7-参考资料" aria-label="Permalink to “7. 参考资料”">​</a></h2><ol><li><a href="https://www.nvidia.com/en-us/data-center/h100.md" target="_blank" rel="noreferrer">NVIDIA H100 GPU</a>：H100 的内存、带宽、NVLink 和算力口径说明。</li><li><a href="https://www.nvidia.com/en-us/data-center/h200.md" target="_blank" rel="noreferrer">NVIDIA H200 GPU</a>：141 GB HBM3e 和 4.8 TB/s 内存带宽。</li><li><a href="https://docs.nvidia.com/enterprise-reference-architectures/hgx-ai-factory-h100-h200-b200/latest/components.html" target="_blank" rel="noreferrer">NVIDIA HGX H100/H200/B200 Components</a>：B200 内存、带宽及 NVLink/NVSwitch 配置。</li><li><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3" target="_blank" rel="noreferrer">华为企业业务：Atlas 800T A3</a>：A3 训练服务器的设备内存与整机配置。</li><li><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">华为企业业务：Atlas 900 A3 SuperPoD</a>：A3 超节点规模、统一编址和 D2D 带宽。</li><li><a href="https://www.hiascend.com/hardware/accelerator-card" target="_blank" rel="noreferrer">昇腾社区：Atlas 350 加速卡</a>：950PR 加速卡的内存、算力、PCIe 和卡间互联。</li><li><a href="https://www.hiascend.com/hardware/cluster?tag=950" target="_blank" rel="noreferrer">昇腾社区：Atlas 950 SuperPoD</a>：950DT 超节点的设备内存和系统配置。</li><li><a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">Zuo et al.：Serving Large Language Models on Huawei CloudMatrix384</a>：CloudMatrix384 的芯片、节点和三个通信平面。</li><li><a href="https://gitee.com/ascend/pytorch" target="_blank" rel="noreferrer">Ascend PyTorch 适配</a>：torch_npu 项目、版本和安装说明。</li><li><a href="https://docs.vllm.ai/projects/ascend/en/main/user_guide/support_matrix/supported_models.html" target="_blank" rel="noreferrer">vLLM-Ascend Supported Models</a>：模型、硬件及功能支持状态。</li><li><a href="https://llamafactory.readthedocs.io/zh-cn/latest/multibackend/npu/npu_training.html" target="_blank" rel="noreferrer">LLaMA-Factory：NPU 训练</a>：支持设备、训练方式、分布式和融合算子。</li><li><a href="https://swift.readthedocs.io/en/latest/BestPractices/NPU-support.html" target="_blank" rel="noreferrer">ms-swift：NPU Support</a>：支持范围、环境、训练、部署及未验证项目。</li><li><a href="https://verl.readthedocs.io/en/latest/ascend_tutorial/get_start/install_guidance.html" target="_blank" rel="noreferrer">verl：Ascend Install Guidance</a>：昇腾硬件和训推后端组合。</li><li><a href="https://jianzhnie.github.io/llmtechsite/ascend/architecture/ascend-hardware-architecture" target="_blank" rel="noreferrer">昇腾硬件架构：达芬奇架构、910C/A3 与 950</a>：站内的芯片、存储、互联和实机配置说明。</li><li><a href="https://jianzhnie.github.io/llmtechsite/ascend/moe/deepep-comparison" target="_blank" rel="noreferrer">DeepEP 与 DeepEP-Ascend：专家并行通信方案对比</a>：MoE 通信后端和实现差异。</li><li><a href="https://jianzhnie.github.io/llmtechsite/ascend/training/npu-fusion-attention" target="_blank" rel="noreferrer">昇腾 NPU 融合注意力算子详解与迁移指南</a>：注意力算子接口和迁移注意事项。</li></ol>`,44)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};